/* 이스라엘(예루살렘) 기준 방향 */
const IL=[35.23,31.78],DIRS=["동","북동","북","북서","서","남서","남","남동"];
const ilDir=(lo,la)=>{const dx=(lo-IL[0])*Math.cos(IL[1]*Math.PI/180),dy=la-IL[1];return DIRS[Math.round(Math.atan2(dy,dx)/(Math.PI/4)+8)%8]};
