/* ---------- 게임 판 ---------- */
function newGame(n=1){
  const ks=shuf(Object.keys(G).flatMap(k=>[k,k,k,k]));
  let gi=0;const cells=[];
  for(let i=0;i<24;i++)cells.push(CORNER[i]||{t:"game",k:ks[gi],p:PLACES[gi++]});
  B={v:2,lv:CFG.lv,turns:TURNS,round:1,cur:0,cells,phase:"roll",dice:[1,1],used:{},pending:null,msg:"",
    players:Array.from({length:n},(_,i)=>({name:"",color:COLORS[i],pos:0,score:0,skip:false}))};
  if(n===2)B.phase="wait";else save();
}
function openOv(){
  const ov=document.createElement("div");ov.className="overlay bm-ov";V.ov=ov;document.body.appendChild(ov);
  const poll=setInterval(roomPoll,2500);
  const mo=new MutationObserver(()=>{if(!ov.isConnected){mo.disconnect();clearInterval(poll);stopAll();if(V.ov===ov)V.ov=null;if(S.view==="bible")rerender()}});
  mo.observe(document.body,{childList:true});
  ov.addEventListener("click",onAct);
}
function openBoard(){if(live())return;A=B;openOv();resume()}
function openSolo(k){
  if(live())return;
  A={solo:true,lv:CFG.lv,used:SOLO[CFG.lv],phase:"intro",pending:{k,m:1,p:""},cur:0,players:[{color:COLORS[0],score:0}]};
  openOv();intro();
}
function resume(){
  drawBoard();
  if(B.phase==="end")drawEnd();
  else if(!myTurn())return;
  else if(B.phase==="move")land();
  else if(B.phase==="intro")intro();
}
function onAct(e){
  const b=e.target.closest("[data-bm]");if(!b)return;
  const a=b.dataset.bm;
  if(a==="exit")V.ov.remove();
  else if(a==="roll")roll();
  else if(a==="next")nextTurn();
  else if(a==="solo"&&B&&B.room){B.phase="roll";goSolo(true)}
  else if(a==="start")startMini();
  else if(a==="again"){stopAll();A.phase="intro";startMini()}
  else if(a==="board"){stopAll();drawBoard()}
  else if(a==="done"){B=null;A=null;save();V.ov.remove()}
}
