  if(B.phase==="wait")return `<p class="bm-msg">방 번호<br><b class="bm-rcode num">${esc(B.room?B.room.code:"")}</b><br><small>상대가 이 번호로 들어오기를 기다려요</small></p><button type="button" class="btn" data-bm="solo">혼자 시작</button>`;
  if(!myTurn())return `<p class="bm-msg"><b style="color:${p.color}">${esc(p.name)}</b> 차례예요<br><small>${esc(B.msg||(B.phase==="intro"?"게임 중이에요":"기다려 주세요"))}</small></p>${dice}`;
  if(B.phase==="next")return `<p class="bm-msg">${esc(B.msg)}</p>${dice}<button type="button" class="btn primary" data-bm="next">다음으로</button>`;
  return `<p class="bm-msg" id="bmMsg"><b>${Math.min(B.round,B.turns)}라운드</b>${B.msg?`<br><small>${esc(B.msg)}</small>`:""}</p>${dice}<button type="button" class="btn primary" data-bm="roll" id="bmRoll">주사위 굴리기</button>`;
